INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Routenverfolgung nur für IPv6-Netze gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Funktioniert auch mit IPv4"}, {"text": "Ja", "correct": false, "because": "Protokollunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für die Routenverfolgung?', 3, '[{"text": "traceroute", "correct": true, "because": "Zeigt Pfad zu Ziel"}, {"text": "ping", "correct": false, "because": "Nur Erreichbarkeit"}, {"text": "ipconfig", "correct": false, "because": "Konfigurationsanzeige"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert die Routenverfolgung?', 5, '[{"text": "Hop-by-Hop-Pfad", "correct": true, "because": "Zeigt Router im Weg"}, {"text": "Latenz pro Hop", "correct": true, "because": "Misst Verzögerung"}, {"text": "Bandbreitenlimit", "correct": false, "because": "Nicht direkt gemessen"}, {"text": "DNS-Server", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Routenverfolgung zeigt Engpässe. b) Sie nutzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMP oder UDP, nicht TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Routenverfolgung?', 4, '[{"text": "Hop-Latenz", "correct": false, "because": "Zeigt Engpässe"}, {"text": "Router-IPs", "correct": false, "because": "Definiert Pfad"}, {"text": "Dateninhalt", "correct": true, "because": "Nur Pfadanalyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Routenverfolgung immer alle Hops zeigt?', 2, '[{"text": "Nein", "correct": true, "because": "Firewalls können blockieren"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt traceroute standardmäßig?', 3, '[{"text": "ICMP", "correct": true, "because": "Echo für Pfadanalyse"}, {"text": "TCP", "correct": false, "because": "Nicht Standard"}, {"text": "HTTP", "correct": false, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme kann die Routenverfolgung aufdecken?', 5, '[{"text": "Hohe Latenz", "correct": true, "because": "Zeigt Engpässe"}, {"text": "Nicht erreichbare Hops", "correct": true, "because": "Unterbrechungen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht analysiert"}, {"text": "IP-Konflikte", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Routenverfolgung misst Latenz. b) Sie zeigt nur lokale Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pfad geht über Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Routenverfolgung?', 4, '[{"text": "Ziel-IP", "correct": false, "because": "Definiert Endpunkt"}, {"text": "ICMP", "correct": false, "because": "Kernprotokoll"}, {"text": "Webserver", "correct": true, "because": "Nicht Pfad-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt Routenverfolgung die Bandbreite?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Latenz und Pfad"}, {"text": "Ja", "correct": false, "because": "Andere Tools nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis zeigt einen Engpass?', 4, '[{"text": "Hohe Latenz bei einem Hop", "correct": true, "because": "Verzögerung sichtbar"}, {"text": "Echo Reply von Ziel", "correct": false, "because": "Erfolg, kein Engpass"}, {"text": "Router Advertisement", "correct": false, "because": "NDP-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Routenverfolgung nur IPv6 unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 möglich"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Routenverfolgung?', 3, '[{"text": "Hop-Latenz", "correct": true, "because": "Zeigt Engpässe"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "DNS-Namen", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Traceroute zeigt den Pfad. b) Es ersetzt ping.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping bleibt eigenständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Routenverfolgung?', 5, '[{"text": "Pfadvisualisierung", "correct": true, "because": "Hop-by-Hop"}, {"text": "Engpasserkennung", "correct": true, "because": "Latenz sichtbar"}, {"text": "Datenübertragung", "correct": false, "because": "Nur Diagnose"}, {"text": "IP-Zuweisung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Routenverfolgung unwichtig?', 3, '[{"text": "Router-IPs", "correct": false, "because": "Definiert Pfad"}, {"text": "Latenzwerte", "correct": false, "because": "Zeigt Engpässe"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt Routenverfolgung nur ICMP?', 3, '[{"text": "Nein", "correct": true, "because": "Auch UDP möglich"}, {"text": "Ja", "correct": false, "because": "Variiert je nach Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Routenverfolgung Firewall-Probleme zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Timeouts bei Blockade"}, {"text": "Nein", "correct": false, "because": "Indirekt sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antwort zeigt das Ende des Pfads?', 4, '[{"text": "Echo Reply vom Ziel", "correct": true, "because": "Ziel erreicht"}, {"text": "Time Exceeded", "correct": false, "because": "Hop-Limit überschritten"}, {"text": "Destination Unreachable", "correct": false, "because": "Fehler im Netz"}]');
